import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'

import { reportDashboardFullWidthToggled } from 'scenes/dashboard/dashboardEvents'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardWidthLogicValues {
    fullWidth: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardWidthLogicActions {
    toggleFullWidth: () => {
        value: true
    }
}

export type dashboardWidthLogicType = MakeLogicType<dashboardWidthLogicValues, dashboardWidthLogicActions>

export const dashboardWidthLogic = kea<dashboardWidthLogicType>([
    // pinned: the path is the localStorage key; renaming it resets every user's choice
    path(['products', 'dashboards', 'frontend', 'dashboardWidthLogic']),
    actions({
        toggleFullWidth: true,
    }),
    reducers({
        fullWidth: [
            true,
            { persist: true },
            {
                toggleFullWidth: (state) => !state,
            },
        ],
    }),
    listeners(({ values }) => ({
        toggleFullWidth: () => {
            reportDashboardFullWidthToggled(values.fullWidth)
        },
    })),
])
